// DeleteFile is the resolver for the deleteFile field.
func (r *mutationResolver) DeleteFile(ctx context.Context, id string) (bool, error) {
	user, err := RequireAuth(ctx)
	if err != nil {
		return false, err
	}

	fileUUID, err := uuid.Parse(id)
	if err != nil {
		return false, fmt.Errorf("invalid file ID: %w", err)
	}

	// First check if file exists at all
	var file db.File
	if err := r.DB.Where("id = ?", fileUUID).First(&file).Error; err != nil {
		if errors.Is(err, gorm.ErrRecordNotFound) {
			return false, fmt.Errorf("FILE_NOT_FOUND: The file you're trying to delete does not exist or has already been deleted")
		}
		return false, fmt.Errorf("DATABASE_ERROR: Failed to check file existence: %w", err)
	}

	// Check ownership
	if file.OwnerID != user.ID {
		// Get file owner info for better error message
		var owner db.User
		r.DB.Where("id = ?", file.OwnerID).First(&owner)
		return false, fmt.Errorf("ACCESS_DENIED: You cannot delete '%s' because it belongs to %s. Only the file owner can delete this file", file.Name, owner.Name)
	}

	// Get file content info
	var content db.FileContent
	if err := r.DB.Where("content_hash = ?", file.ContentHash).First(&content).Error; err != nil {
		return false, fmt.Errorf("file content not found: %w", err)
	}

	// Start transaction
	tx := r.DB.Begin()

	// Delete file record
	if err := tx.Delete(&file).Error; err != nil {
		tx.Rollback()
		return false, fmt.Errorf("failed to delete file record: %w", err)
	}

	// Update reference count
	if err := tx.Model(&content).Update("reference_count", gorm.Expr("reference_count - ?", 1)).Error; err != nil {
		tx.Rollback()
		return false, fmt.Errorf("failed to update reference count: %w", err)
	}

	// Update user storage
	if err := tx.Model(user).Update("storage_used", gorm.Expr("storage_used - ?", file.Size)).Error; err != nil {
		tx.Rollback()
		return false, fmt.Errorf("failed to update user storage: %w", err)
	}

	// If no more references, delete the actual file
	var updatedContent db.FileContent
	if err := tx.Where("content_hash = ?", file.ContentHash).First(&updatedContent).Error; err == nil {
		if updatedContent.ReferenceCount <= 0 {
			// Delete file from storage
			if err := r.Storage.DeleteFile(file.ContentHash); err != nil {
				tx.Rollback()
				return false, fmt.Errorf("failed to delete file from storage: %w", err)
			}
			// Delete content record
			if err := tx.Delete(&updatedContent).Error; err != nil {
				tx.Rollback()
				return false, fmt.Errorf("failed to delete content record: %w", err)
			}
		}
	}

	tx.Commit()
	
	// Log audit event
	r.Audit.LogFileOperation(ctx, &user.ID, audit.ActionFileDelete, file.ID, file.Name, file.Size, file.MimeType)
	
	// Publish real-time events after successful deletion
	activityEvent := realtime.CreateActivityEvent(
		realtime.EventFileDeleted,
		user.ID.String(),
		user.Name,
		fmt.Sprintf("%s deleted file: %s", user.Name, file.Name),
		nil,
	)
	realtime.GlobalPublisher.PublishActivity(activityEvent)

	return true, nil
}

// ShareFile is the resolver for the shareFile field.
func (r *mutationResolver) ShareFile(ctx context.Context, id string, userID string) (*model.FileShare, error) {
	user, err := RequireAuth(ctx)
	if err != nil {
		return nil, err
	}

	// Parse UUIDs
	fileUUID, err := uuid.Parse(id)
	if err != nil {
		return nil, fmt.Errorf("invalid file ID: %w", err)
	}

	targetUserUUID, err := uuid.Parse(userID)
	if err != nil {
		return nil, fmt.Errorf("invalid user ID: %w", err)
	}

	// Verify file exists and user owns it
	var dbFile db.File
	if err := r.DB.Where("id = ? AND owner_id = ?", fileUUID, user.ID).First(&dbFile).Error; err != nil {
		return nil, fmt.Errorf("file not found or access denied")
	}

	// Verify target user exists
	var targetUser db.User
	if err := r.DB.Where("id = ?", targetUserUUID).First(&targetUser).Error; err != nil {
		return nil, fmt.Errorf("target user not found")
	}

	// Check if already shared
	var existingShare db.FileShare
	if err := r.DB.Where("file_id = ? AND user_id = ?", fileUUID, targetUserUUID).First(&existingShare).Error; err == nil {
		return nil, fmt.Errorf("file is already shared with this user")
	}

	// Create new share
	share := db.FileShare{
		ID:     uuid.New(),
		FileID: fileUUID,
		UserID: targetUserUUID,
	}

	if err := r.DB.Create(&share).Error; err != nil {
		return nil, fmt.Errorf("failed to create file share: %w", err)
	}

	// Load the share with relationships
	if err := r.DB.Preload("File").Preload("User").Where("id = ?", share.ID).First(&share).Error; err != nil {
		return nil, fmt.Errorf("failed to load created share: %w", err)
	}

	result := &model.FileShare{
		ID: share.ID.String(),
		File: &model.File{
			ID:            share.File.ID.String(),
			Name:          share.File.Name,
			ContentHash:   share.File.ContentHash,
			MimeType:      share.File.MimeType,
			Size:          int(share.File.Size),
			IsPublic:      share.File.IsPublic,
			DownloadCount: int(share.File.DownloadCount),
			CreatedAt:     share.File.CreatedAt,
			UpdatedAt:     share.File.UpdatedAt,
		},
		User: &model.User{
			ID:           share.User.ID.String(),
			Email:        share.User.Email,
			Name:         share.User.Name,
			Role:         share.User.Role,
			StorageUsed:  int(share.User.StorageUsed),
			StorageQuota: int(share.User.StorageQuota),
			CreatedAt:    share.User.CreatedAt,
			UpdatedAt:    share.User.UpdatedAt,
		},
		CreatedAt: share.CreatedAt,
		UpdatedAt: share.UpdatedAt,
	}

	// Publish real-time events
	activityEvent := realtime.CreateActivityEvent(
		realtime.EventFileShared,
		user.ID.String(),
		user.Name,
		fmt.Sprintf("%s shared file '%s' with %s", user.Name, share.File.Name, share.User.Name),
		nil,
	)
	realtime.GlobalPublisher.PublishActivity(activityEvent)

	return result, nil
}

// UnshareFile is the resolver for the unshareFile field.
func (r *mutationResolver) UnshareFile(ctx context.Context, id string, userID string) (bool, error) {
	user, err := RequireAuth(ctx)
	if err != nil {
		return false, err
	}

	// Parse UUIDs
	fileUUID, err := uuid.Parse(id)
	if err != nil {
		return false, fmt.Errorf("invalid file ID: %w", err)
	}

	targetUserUUID, err := uuid.Parse(userID)
	if err != nil {
		return false, fmt.Errorf("invalid user ID: %w", err)
	}

	// Verify file exists and user owns it
	var dbFile db.File
	if err := r.DB.Where("id = ? AND owner_id = ?", fileUUID, user.ID).First(&dbFile).Error; err != nil {
		return false, fmt.Errorf("file not found or access denied")
	}

	// Delete the share
	result := r.DB.Where("file_id = ? AND user_id = ?", fileUUID, targetUserUUID).Delete(&db.FileShare{})
	if result.Error != nil {
		return false, fmt.Errorf("failed to unshare file: %w", result.Error)
	}

	return result.RowsAffected > 0, nil
}

