// Files is the resolver for the files field.
func (r *queryResolver) Files(ctx context.Context, filter *model.FileFilter, first *int, after *string) ([]*model.File, error) {
	user, err := RequireAuth(ctx)
	if err != nil {
		return nil, err
	}

	query := r.DB.Where("owner_id = ? OR is_public = ?", user.ID, true)

	// Apply filters if provided
	if filter != nil {
		if filter.Filename != nil {
			query = query.Where("name ILIKE ?", "%"+*filter.Filename+"%")
		}
		if filter.MimeType != nil {
			if strings.HasSuffix(*filter.MimeType, "/") {
				// Filter by MIME type prefix (e.g., "image/")
				query = query.Where("mime_type LIKE ?", *filter.MimeType+"%")
			} else {
				// Filter by exact MIME type
				query = query.Where("mime_type = ?", *filter.MimeType)
			}
		}
		if filter.MinSize != nil {
			query = query.Where("size >= ?", *filter.MinSize)
		}
		if filter.MaxSize != nil {
			query = query.Where("size <= ?", *filter.MaxSize)
		}
		if filter.FromDate != nil {
			query = query.Where("created_at >= ?", *filter.FromDate)
		}
		if filter.ToDate != nil {
			query = query.Where("created_at <= ?", *filter.ToDate)
		}
		if filter.Uploader != nil {
			// Join with users table to filter by uploader name
			query = query.Joins("JOIN users ON files.owner_id = users.id").
				Where("users.name ILIKE ?", "%"+*filter.Uploader+"%")
		}
		// TODO: Add tags filter when tag relationships are implemented
	}

	// Apply pagination
	limit := 10 // default
	if first != nil && *first > 0 {
		limit = *first
	}
	query = query.Limit(limit).Preload("Owner")

	var files []db.File
	if err := query.Find(&files).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch files: %w", err)
	}

	var result []*model.File
	for _, file := range files {
		result = append(result, &model.File{
			ID:            file.ID.String(),
			Name:          file.Name,
			ContentHash:   file.ContentHash,
			MimeType:      file.MimeType,
			Size:          int(file.Size),
			IsPublic:      file.IsPublic,
			DownloadCount: file.DownloadCount,
			CreatedAt:     file.CreatedAt,
			UpdatedAt:     file.UpdatedAt,
			Owner: &model.User{
				ID:           file.Owner.ID.String(),
				Email:        file.Owner.Email,
				Name:         file.Owner.Name,
				Role:         file.Owner.Role,
				StorageUsed:  int(file.Owner.StorageUsed),
				StorageQuota: int(file.Owner.StorageQuota),
				CreatedAt:    file.Owner.CreatedAt,
				UpdatedAt:    file.Owner.UpdatedAt,
			},
		})
	}

	return result, nil
}

// Folder is the resolver for the folder field.
func (r *queryResolver) Folder(ctx context.Context, id string) (*model.Folder, error) {
	user, err := RequireAuth(ctx)
	if err != nil {
		return nil, err
	}

	var folder db.Folder
	err = r.DB.Preload("Owner").Preload("Parent").Preload("Files").Preload("Files.Owner").Where("id = ? AND (owner_id = ? OR is_public = ?)", id, user.ID, true).First(&folder).Error
	if err != nil {
		return nil, err
	}

	// Convert parent if exists
	var parent *model.Folder
	if folder.Parent != nil {
		parent = &model.Folder{
			ID:   folder.Parent.ID.String(),
			Name: folder.Parent.Name,
		}
	}

	// Convert files
	var files []*model.File
	for _, file := range folder.Files {
		var fileFolder *model.Folder
		if file.Folder != nil {
			fileFolder = &model.Folder{
				ID:   file.Folder.ID.String(),
				Name: file.Folder.Name,
			}
		}

		files = append(files, &model.File{
			ID:            file.ID.String(),
			Name:          file.Name,
			ContentHash:   file.ContentHash,
			MimeType:      file.MimeType,
			Size:          int(file.Size),
			IsPublic:      file.IsPublic,
			DownloadCount: file.DownloadCount,
			CreatedAt:     file.CreatedAt,
			UpdatedAt:     file.UpdatedAt,
			Owner: &model.User{
				ID:           file.Owner.ID.String(),
				Name:         file.Owner.Name,
				Email:        file.Owner.Email,
				Role:         file.Owner.Role,
				StorageUsed:  int(file.Owner.StorageUsed),
				StorageQuota: int(file.Owner.StorageQuota),
				CreatedAt:    file.Owner.CreatedAt,
				UpdatedAt:    file.Owner.UpdatedAt,
			},
			Folder: fileFolder,
		})
	}

	return &model.Folder{
		ID:        folder.ID.String(),
		Name:      folder.Name,
		IsPublic:  folder.IsPublic,
		CreatedAt: folder.CreatedAt,
		UpdatedAt: folder.UpdatedAt,
		Owner: &model.User{
			ID:           folder.Owner.ID.String(),
			Name:         folder.Owner.Name,
			Email:        folder.Owner.Email,
			Role:         folder.Owner.Role,
			StorageUsed:  int(folder.Owner.StorageUsed),
			StorageQuota: int(folder.Owner.StorageQuota),
			CreatedAt:    folder.Owner.CreatedAt,
			UpdatedAt:    folder.Owner.UpdatedAt,
		},
		Parent: parent,
		Files:  files,
	}, nil
}

