// StorageStats is the resolver for the storageStats field.
func (r *queryResolver) StorageStats(ctx context.Context) (*model.StorageStats, error) {
	user, err := RequireAuth(ctx)
	if err != nil {
		return nil, err
	}

	// Calculate original storage (sum of all file sizes)
	var totalOriginalSize int64
	r.DB.Model(&db.File{}).Select("COALESCE(SUM(size), 0)").
		Where("owner_id = ?", user.ID).Row().Scan(&totalOriginalSize)

	// Calculate deduplicated storage (sum of unique file sizes by content_hash)
	var totalDeduplicatedSize int64
	r.DB.Raw(`
		SELECT COALESCE(SUM(size), 0) 
		FROM (
			SELECT DISTINCT content_hash, size 
			FROM files 
			WHERE owner_id = ?
		) as unique_files
	`, user.ID).Row().Scan(&totalDeduplicatedSize)

	savedStorage := totalOriginalSize - totalDeduplicatedSize
	savingsPercentage := float64(0)
	if totalOriginalSize > 0 {
		savingsPercentage = float64(savedStorage) / float64(totalOriginalSize) * 100
	}

	return &model.StorageStats{
		TotalStorage:      int(totalDeduplicatedSize),
		OriginalStorage:   int(totalOriginalSize),
		SavedStorage:      int(savedStorage),
		SavingsPercentage: savingsPercentage,
	}, nil
}

// AnalyticsSummary is the resolver for the analyticsSummary field.
func (r *queryResolver) AnalyticsSummary(ctx context.Context, days *int) (*model.AnalyticsSummary, error) {
	// Check if user is admin
	user, err := RequireAuth(ctx)
	if err != nil {
		return nil, err
	}
	if user.Role != "admin" {
		return nil, errors.New("ACCESS_DENIED: Only admins can access analytics data")
	}

	defaultDays := 30
	if days != nil {
		defaultDays = *days
	}

	// Get all analytics data
	uploadTrends, err := r.getUploadTrends(defaultDays)
	if err != nil {
		return nil, fmt.Errorf("failed to get upload trends: %w", err)
	}

	userActivity, err := r.getUserActivity()
	if err != nil {
		return nil, fmt.Errorf("failed to get user activity: %w", err)
	}

	fileTypeStats, err := r.getFileTypeStats()
	if err != nil {
		return nil, fmt.Errorf("failed to get file type stats: %w", err)
	}

	sharingStats, err := r.getSharingStats()
	if err != nil {
		return nil, fmt.Errorf("failed to get sharing stats: %w", err)
	}

	storageStats, err := r.StorageStats(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get storage stats: %w", err)
	}

	return &model.AnalyticsSummary{
		UploadTrends:  uploadTrends,
		UserActivity:  userActivity,
		FileTypeStats: fileTypeStats,
		SharingStats:  sharingStats,
		StorageStats:  storageStats,
	}, nil
}

