// AuditLogs is the resolver for the auditLogs field.
func (r *queryResolver) AuditLogs(ctx context.Context, resourceID *string) ([]*model.AuditLog, error) {
	user, err := RequireAuth(ctx)
	if err != nil {
		return nil, err
	}

	// Only admins can view all audit logs
	if user.Role != "admin" && user.Role != "moderator" {
		return nil, fmt.Errorf("insufficient permissions")
	}

	var logs []*db.AuditLog
	query := r.DB.Preload("User").Order("created_at DESC")

	// Filter by resource ID if provided
	if resourceID != nil {
		query = query.Where("resource_id = ?", *resourceID)
	}

	// Limit to recent 1000 logs to avoid performance issues
	query = query.Limit(1000)

	if err := query.Find(&logs).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch audit logs: %w", err)
	}

	// Convert to GraphQL models
	var result []*model.AuditLog
	for _, log := range logs {
		var user *model.User
		if log.User != nil {
			user = &model.User{
				ID:           log.User.ID.String(),
				Email:        log.User.Email,
				Name:         log.User.Name,
				Role:         log.User.Role,
				StorageUsed:  int(log.User.StorageUsed),
				StorageQuota: int(log.User.StorageQuota),
				CreatedAt:    log.User.CreatedAt,
			}
		}

		result = append(result, &model.AuditLog{
			ID:           log.ID.String(),
			User:         user,
			Action:       log.Action,
			ResourceType: log.ResourceType,
			ResourceID:   log.ResourceID.String(),
			Details:      &log.Details,
			CreatedAt:    log.CreatedAt,
		})
	}

	return result, nil
}

