// Mutation returns generated.MutationResolver implementation.
func (r *Resolver) Mutation() generated.MutationResolver { return &mutationResolver{r} }

// Query returns generated.QueryResolver implementation.
func (r *Resolver) Query() generated.QueryResolver { return &queryResolver{r} }

// Subscription returns generated.SubscriptionResolver implementation.
func (r *Resolver) Subscription() generated.SubscriptionResolver { return &subscriptionResolver{r} }

type mutationResolver struct{ *Resolver }
type queryResolver struct{ *Resolver }
type subscriptionResolver struct{ *Resolver }

// !!! WARNING !!!
// The code below was going to be deleted when updating resolvers. It has been copied here so you have
// one last chance to move it out of harms way if you want. There are two reasons this happens:
//  - When renaming or deleting a resolver the old code will be put in here. You can safely delete
//    it when you're done.
//  - You have helper methods in this file. Move them out to keep these resolver files clean.

func (r *queryResolver) getUploadTrends(days int) ([]*model.UploadTrend, error) {
	var trends []*model.UploadTrend

	// Get upload trends for the last N days
	for i := days - 1; i >= 0; i-- {
		date := time.Now().AddDate(0, 0, -i).Format("2006-01-02")

		var count int64
		var totalSize int64

		startOfDay := time.Now().AddDate(0, 0, -i).Truncate(24 * time.Hour)
		endOfDay := startOfDay.Add(24 * time.Hour)

		r.DB.Model(&db.File{}).Where("created_at >= ? AND created_at < ?", startOfDay, endOfDay).Count(&count)
		r.DB.Model(&db.File{}).Where("created_at >= ? AND created_at < ?", startOfDay, endOfDay).Select("COALESCE(SUM(size), 0)").Scan(&totalSize)

		trends = append(trends, &model.UploadTrend{
			Date:  date,
			Count: int(count),
			Size:  int(totalSize),
		})
	}

	return trends, nil
}
func (r *queryResolver) getUserActivity() ([]*model.UserActivity, error) {
	var activities []*model.UserActivity

	type userStats struct {
		UserID       string
		UserName     string
		UserEmail    string
		FileCount    int64
		TotalSize    int64
		LastActivity *time.Time
		SharingCount int64
	}

	var stats []userStats

	// Get user activity stats
	err := r.DB.Raw(`
		SELECT
			u.id as user_id,
			u.name as user_name,
			u.email as user_email,
			COUNT(DISTINCT f.id) as file_count,
			COALESCE(SUM(f.size), 0) as total_size,
			MAX(f.created_at) as last_activity,
			(SELECT COUNT(*) FROM file_shares fs WHERE fs.user_id = u.id) +
			(SELECT COUNT(*) FROM folder_shares fos WHERE fos.user_id = u.id) as sharing_count
		FROM users u
		LEFT JOIN files f ON f.owner_id = u.id
		GROUP BY u.id, u.name, u.email
		ORDER BY file_count DESC
	`).Scan(&stats).Error

	if err != nil {
		return nil, err
	}

	for _, stat := range stats {
		activities = append(activities, &model.UserActivity{
			UserID:       stat.UserID,
			UserName:     stat.UserName,
			UserEmail:    stat.UserEmail,
			FileCount:    int(stat.FileCount),
			TotalSize:    int(stat.TotalSize),
			LastActivity: stat.LastActivity,
			SharingCount: int(stat.SharingCount),
		})
	}

	return activities, nil
}
func (r *queryResolver) getFileTypeStats() ([]*model.FileTypeStats, error) {
	var stats []*model.FileTypeStats

	type mimeTypeStats struct {
		MimeType  string
		Count     int64
		TotalSize int64
	}

	var mimeStats []mimeTypeStats

	err := r.DB.Model(&db.File{}).
		Select("mime_type, COUNT(*) as count, SUM(size) as total_size").
		Group("mime_type").
		Order("count DESC").
		Scan(&mimeStats).Error

	if err != nil {
		return nil, err
	}

	// Calculate total files for percentage
	var totalFiles int64
	r.DB.Model(&db.File{}).Count(&totalFiles)

	for _, stat := range mimeStats {
		percentage := float64(stat.Count) / float64(totalFiles) * 100
		if totalFiles == 0 {
			percentage = 0
		}

		stats = append(stats, &model.FileTypeStats{
			MimeType:   stat.MimeType,
			Count:      int(stat.Count),
			TotalSize:  int(stat.TotalSize),
			Percentage: percentage,
		})
	}

	return stats, nil
}
func (r *queryResolver) getSharingStats() (*model.SharingStats, error) {
	var totalShares int64
	var publicFiles int64
	var publicFolders int64
	var userShares int64

	// Count sharing stats
	r.DB.Model(&db.FileShare{}).Count(&totalShares)
	r.DB.Model(&db.File{}).Where("is_public = ?", true).Count(&publicFiles)
	r.DB.Model(&db.Folder{}).Where("is_public = ?", true).Count(&publicFolders)

	// User shares = file shares + folder shares
	var folderShares int64
	r.DB.Model(&db.FolderShare{}).Count(&folderShares)
	userShares = totalShares + folderShares

	// Get most shared files
	var mostSharedFiles []*model.File
	var dbFiles []db.File

	err := r.DB.Raw(`
		SELECT f.*, COUNT(fs.id) as share_count
		FROM files f
		LEFT JOIN file_shares fs ON fs.file_id = f.id
		GROUP BY f.id
		ORDER BY share_count DESC, f.download_count DESC
		LIMIT 5
	`).Find(&dbFiles).Error

	if err != nil {
		return nil, err
	}

	for _, file := range dbFiles {
		mostSharedFiles = append(mostSharedFiles, &model.File{
			ID:            file.ID.String(),
			Name:          file.Name,
			ContentHash:   file.ContentHash,
			MimeType:      file.MimeType,
			Size:          int(file.Size),
			IsPublic:      file.IsPublic,
			DownloadCount: int(file.DownloadCount),
			CreatedAt:     file.CreatedAt,
			UpdatedAt:     file.UpdatedAt,
		})
	}

	// Get most shared folders
	var mostSharedFolders []*model.Folder
	var dbFolders []db.Folder

	err = r.DB.Raw(`
		SELECT f.*, COUNT(fs.id) as share_count
		FROM folders f
		LEFT JOIN folder_shares fs ON fs.folder_id = f.id
		GROUP BY f.id
		ORDER BY share_count DESC
		LIMIT 5
	`).Find(&dbFolders).Error

	if err != nil {
		return nil, err
	}

	for _, folder := range dbFolders {
		mostSharedFolders = append(mostSharedFolders, &model.Folder{
			ID:        folder.ID.String(),
			Name:      folder.Name,
			IsPublic:  folder.IsPublic,
			CreatedAt: folder.CreatedAt,
			UpdatedAt: folder.UpdatedAt,
		})
	}

	return &model.SharingStats{
		TotalShares:       int(totalShares),
		PublicFiles:       int(publicFiles),
		PublicFolders:     int(publicFolders),
		UserShares:        int(userShares),
		MostSharedFiles:   mostSharedFiles,
		MostSharedFolders: mostSharedFolders,
	}, nil
}
func (r *mutationResolver) getAllFilesInFolder(tx *gorm.DB, folderId string, files *[]db.File) error {
	// Get direct files in this folder
	var directFiles []db.File
	if err := tx.Where("folder_id = ?", folderId).Find(&directFiles).Error; err != nil {
		return err
	}
	*files = append(*files, directFiles...)

	// Get all subfolders and recurse
	var subfolders []db.Folder
	if err := tx.Where("parent_id = ?", folderId).Find(&subfolders).Error; err != nil {
		return err
	}

	for _, subfolder := range subfolders {
		if err := r.getAllFilesInFolder(tx, subfolder.ID.String(), files); err != nil {
			return err
		}
	}

	return nil
}
func (r *mutationResolver) deleteFileWithDeduplication(tx *gorm.DB, file db.File) error {
	// Get the file content record
	var content db.FileContent
	if err := tx.Where("content_hash = ?", file.ContentHash).First(&content).Error; err != nil {
		return err
	}

	// Delete the file record
	if err := tx.Delete(&file).Error; err != nil {
		return err
	}

	// Decrement reference count
	content.ReferenceCount--
	if content.ReferenceCount <= 0 {
		// No more references, delete the physical file and content record
		if err := r.Storage.DeleteFile(file.ContentHash); err != nil {
			return fmt.Errorf("failed to delete physical file: %w", err)
		}
		if err := tx.Delete(&content).Error; err != nil {
			return fmt.Errorf("failed to delete content record: %w", err)
		}
	} else {
		// Update reference count
		if err := tx.Save(&content).Error; err != nil {
			return err
		}
	}

	return nil
}
